const items = $input.all();
const FLOOR = 7.0;

function ownershipRank(signal) {
  if (signal === 'Strong') return 3;
  if (signal === 'Moderate') return 2;
  if (signal === 'Weak') return 1;
  return 0;
}

const candidates = items.map(item => ({
  id: item.json.id,
  name: item.json.property_name,
  overall_score: item.json.property_overall_score,
  technical_score: item.json.property_technical_score,
  ownership_signal: item.json.property_ownership_signal,
  ownership_rank: ownershipRank(item.json.property_ownership_signal),
}));

const totalApplicants = candidates.length;

// Low-volume rule: under 10 total applicants skips floor/percentile entirely
if (totalApplicants < 10) {
  return candidates.map(c => ({
    json: {
      id: c.id,
      name: c.name,
      batch_status: 'Human-Review',
      percentile_rank: null,
      reason: 'Low volume batch (<10 total applicants), routed to Human Review per policy'
    }
  }));
}

const survivors = candidates.filter(c => c.overall_score >= FLOOR);
const nonSurvivors = candidates.filter(c => c.overall_score < FLOOR);

survivors.sort((a, b) => {
  if (b.overall_score !== a.overall_score) return b.overall_score - a.overall_score;
  if (b.technical_score !== a.technical_score) return b.technical_score - a.technical_score;
  return b.ownership_rank - a.ownership_rank;
});

const quota = Math.round(survivors.length * 0.10);

let results = [];

if (quota === 0 || survivors.length === 0) {
  survivors.forEach((c, idx) => {
    results.push({ id: c.id, name: c.name, batch_status: 'Archived-Not-Selected', percentile_rank: idx + 1 });
  });
} else {
  const tieKey = (c) => `${c.overall_score}|${c.technical_score}|${c.ownership_rank}`;
  const cutoffKey = tieKey(survivors[quota - 1]);

  const tieGroupIndices = [];
  survivors.forEach((c, idx) => {
    if (tieKey(c) === cutoffKey) tieGroupIndices.push(idx);
  });

  const groupStraddles = tieGroupIndices.some(idx => idx >= quota) && tieGroupIndices.some(idx => idx < quota);

  survivors.forEach((c, idx) => {
    let status;
    if (groupStraddles && tieKey(c) === cutoffKey) {
      status = 'Human-Review';
    } else if (idx < quota) {
      status = 'Shortlisted';
    } else {
      status = 'Archived-Not-Selected';
    }
    results.push({ id: c.id, name: c.name, batch_status: status, percentile_rank: idx + 1 });
  });
}

nonSurvivors.forEach(c => {
  results.push({ id: c.id, name: c.name, batch_status: 'Archived-Not-Selected', percentile_rank: null });
});

return results.map(r => ({ json: r }));
